import {inspect} from './chart-inspector.js';
// A scoped chapter derived from the original material-history chart.
// Keep its data and brush assets local; never write back to the editor project.
export function mountMaterials(host){
 const root=host.shadowRoot||host.attachShadow({mode:'open'});
 root.replaceChildren();
 const style=document.createElement('style');
 style.textContent="\n:host{display:block;min-width:0;color:#63554b;font-family:\"Huiwen-mincho\",\"汇文明朝体\",serif}\n*{box-sizing:border-box}\n.viewport{width:100%;position:relative}\n.stage{width:3000px;height:2200px;transform-origin:top left}\n.poster{width:3000px;height:2200px;margin:0;padding:150px 180px 160px;transform:scale(.92);transform-origin:center center}\nh2{height:115px;margin:0 0 38px;display:flex;align-items:center;justify-content:center;font-weight:400}\n.title-font{display:block;width:1160px;max-width:100%;font-size:72px;line-height:115px;font-weight:400;letter-spacing:5px;text-align:center}\n.legend{display:flex;align-items:center;justify-content:center;gap:65px;flex-wrap:wrap;margin-top:45px;margin-bottom:70px}\n.legend button{font:inherit;font-size:37px;border:0;background:transparent;padding:5px 0;color:#58473b;opacity:.35;display:inline-flex;align-items:center;cursor:pointer}\n.legend button.on{opacity:1}\n.legend button:focus-visible{outline:2px solid #657b4a;outline-offset:12px}\n.legend i{display:inline-block;width:25px;height:25px;background:var(--c);margin-right:16px;flex-shrink:0}\n.legend button[data-name=\"木器\"] i{border:1px solid #bda58d}\n.chart{width:100%;position:relative}\nsvg{width:100%;height:1600px;display:block;overflow:visible}\nsvg text,.tip{font-family:inherit}\n.era{font-size:19px;fill:#aa9682}.tick{font-size:17px;fill:#998675}\n.tip{position:absolute;pointer-events:none;background:rgba(255,252,246,.96);border:1px solid #d6c7b7;padding:18px 25px;border-radius:7px;box-shadow:0 8px 24px #4a37271a;display:none;font-size:27px;line-height:1.8;z-index:3}\n.tip strong{display:block;color:#544639}.subtle{stroke:#b7a38f;stroke-opacity:.18;stroke-dasharray:4 8}\n@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important}}\n";

 style.textContent+=`:host{font-family:"长卷明朝","Huiwen-mincho","汇文明朝体",serif}.stage{width:100%;transform:none}.poster{width:100%;height:auto;padding:0;transform:none}.poster h2{height:auto;margin:0 0 22px}.title-font{width:100%;font-size:clamp(25px,2.4vw,42px);line-height:1.5;letter-spacing:2px}.legend{gap:16px 32px;margin:0 0 24px}.legend button{font-size:clamp(16px,1.35vw,22px)}.legend i{width:14px;height:14px;margin-right:9px}.chart svg{width:100%;height:auto;aspect-ratio:1360/675}.tip{font-size:17px;padding:12px 16px}.era{font-size:var(--era-size,22px)}.tick{font-size:var(--tick-size,21px)}@media(max-width:700px){.legend{gap:12px 18px}.title-font{font-size:24px}.chart{overflow-x:auto}.chart svg{min-width:780px}.legend button{font-size:16px}}`;
 const template=document.createElement('template');
 template.innerHTML="<div class=\"viewport\"><div class=\"stage\"><article class=\"poster\"><h2 class=\"title-image\" id=\"materials-title\"><span class=\"title-font\">唐—五代—宋食器材质流行强度</span></h2><div class=\"legend\" id=\"legend\"></div><div class=\"chart\" id=\"chart\"><svg id=\"svg\" viewBox=\"0 0 1360 675\" preserveAspectRatio=\"none\" role=\"img\" aria-label=\"唐五代宋食器材质流行强度渐变山峦图\"></svg><div class=\"tip\" id=\"tip\"></div></div></article></div></div>";
 root.append(style,template.content.cloneNode(true));
 const viewport=root.querySelector('.viewport'),stage=root.querySelector('.stage');
 const fit=()=>{stage.style.width='100%';stage.style.height='auto';stage.style.transform='none';viewport.style.height='auto';const width=host.clientWidth;if(width){host.style.setProperty('--tick-size',Math.min(26,Math.max(16,13*1360/width))+'px');host.style.setProperty('--era-size',Math.max(18,16*1360/width)+'px');}};
 const observer=new ResizeObserver(fit);observer.observe(host);fit();
const labels=['初唐','盛唐','中唐','晚唐','五代','北宋前期','北宋中后期','南宋前期','南宋后期'];
const series=[{name:'普通陶器',color:'#ce6557',values:[7,6.9,5.5,5.4,5.3,5.3,5.2,3.5,3.2]},{name:'瓷器',color:'#89c2ab',values:[7,7.8,8.7,9,9,9.8,10,10,10]},{name:'金银器',color:'#D5AD72',values:[5,4.9,4.8,4.8,4.7,4.7,4.6,3.2,3]},{name:'铜器',color:'#eab4a7',values:[7.2,8.7,9,7.3,7.1,5.3,5.2,5,5]},{name:'漆器',color:'#A7B58D',values:[4.1,4.3,4.1,4.2,4.1,4.2,4,4.1,4]},{name:'木器',color:'#bf8d59',values:[2.8,2.9,3,2.9,3,3,3.1,2.9,3]}];
const svg=root.getElementById('svg'),legend=root.getElementById('legend'),tip=root.getElementById('tip'),chart=root.getElementById('chart');const W=1360,H=675,L=28,R=1330,T=55,B=607;const xx=i=>L+(R-L)*i/8,yy=v=>B-(B-T)*v/10;const active=new Set(series.map(s=>s.name));
function interp(a,b,t){return a+(b-a)*t}function smooth(points){let d=`M ${points[0][0]} ${points[0][1]}`;for(let i=0;i<points.length-1;i++){let p0=points[Math.max(0,i-1)],p1=points[i],p2=points[i+1],p3=points[Math.min(points.length-1,i+2)];d+=` C ${p1[0]+(p2[0]-p0[0])/6} ${p1[1]+(p2[1]-p0[1])/6}, ${p2[0]-(p3[0]-p1[0])/6} ${p2[1]-(p3[1]-p1[1])/6}, ${p2[0]} ${p2[1]}`}return d}function esc(s){return s.replaceAll('&','&amp;').replaceAll('<','&lt;')}
function render(){legend.innerHTML=series.map(s=>`<button type="button" aria-pressed="${active.has(s.name)}" class="${active.has(s.name)?'on':''}" style="--c:${s.color}" data-name="${s.name}"><i></i>${s.name}</button>`).join('');legend.querySelectorAll('button').forEach(b=>b.onclick=()=>{const name=b.dataset.name,focused=root.activeElement===b;active.has(name)?active.delete(name):active.add(name);render();if(focused)[...legend.querySelectorAll('button')].find(node=>node.dataset.name===name)?.focus({preventScroll:true})});let defs=`<defs><pattern id="dryBrush" patternUnits="userSpaceOnUse" width="480" height="260"><image href="data:image/png;base64," x="0" y="0" width="480" height="260" preserveAspectRatio="none"/></pattern><mask id="brushMask" maskUnits="userSpaceOnUse" maskContentUnits="userSpaceOnUse" style="mask-type:luminance"><rect x="0" y="0" width="1360" height="675" fill="#fff" opacity=".83"/><rect x="0" y="0" width="1360" height="675" fill="url(#dryBrush)" opacity=".17"/></mask></defs>`;defs=defs.replace('</defs>','')+'<filter id="grain" x="0" y="0" width="100%" height="100%"><feTurbulence type="fractalNoise" baseFrequency="0.65" numOctaves="3" seed="8" result="noise"/><feColorMatrix in="noise" type="saturate" values="0" result="mono"/><feComponentTransfer in="mono"><feFuncA type="linear" slope="0.11"/></feComponentTransfer></filter>';series.forEach((s,i)=>{defs+=`<linearGradient id="g${i}" gradientUnits="userSpaceOnUse" x1="0" y1="${yy(Math.max(...s.values))}" x2="0" y2="${B}"><stop offset="0%" stop-color="${s.color}" stop-opacity=".73"/><stop offset="27%" stop-color="${s.color}" stop-opacity=".45"/><stop offset="67%" stop-color="${s.color}" stop-opacity=".12"/><stop offset="100%" stop-color="${s.color}" stop-opacity="0"/></linearGradient>`});defs+='</defs>';let content=defs;[4,5,7].forEach((i,j)=>content+=`<line class="subtle" x1="${xx(i)}" y1="${T}" x2="${xx(i)}" y2="${B}"/>`);content+=`<text class="era" x="${xx(1.5)}" y="36" text-anchor="middle">唐</text><text class="era" x="${xx(4)}" y="36" text-anchor="middle">五代</text><text class="era" x="${xx(5.7)}" y="36" text-anchor="middle">北宋</text><text class="era" x="${xx(7.5)}" y="36" text-anchor="middle">南宋</text>`;
// Low-value layers in foreground, tall peaks in background; no strong standalone line strokes.
const order=[...series].filter(s=>active.has(s.name)).sort((a,b)=>Math.max(...b.values)-Math.max(...a.values));for(const s of order){let idx=series.indexOf(s);let pts=s.values.map((v,i)=>[xx(i),yy(v)]),top=smooth(pts),area=top+` L ${R} ${B} L ${L} ${B} Z`;content+=`<g class="mountain" data-name="${s.name}"><path d="${area}" fill="url(#g${idx})" mask="url(#brushMask)"/><path d="${top}" fill="none" stroke="${s.color}" stroke-width=".7" stroke-opacity=".11"/></g>`;}
content+=`<rect x="${L}" y="${T}" width="${R-L}" height="${B-T}" fill="#786a56" filter="url(#grain)" opacity=".012" pointer-events="none"/>`;labels.forEach((v,i)=>content+=`<text class="tick" x="${xx(i)}" y="${B+31}" text-anchor="middle">${v}</text>`);content+=`<rect id="hit" x="${L}" y="${T}" width="${R-L}" height="${B-T}" fill="transparent" style="cursor:crosshair"/>`;svg.innerHTML=content;const hit=root.getElementById('hit');
function highlight(name){if(name)inspect(host,name,'材质流行强度 · 唐—五代—宋');svg.querySelectorAll('.mountain').forEach(g=>{let chosen=g.dataset.name===name;g.style.opacity=name?(chosen?'1':'.09'):'1';let stroke=g.querySelectorAll('path')[1];stroke.setAttribute('stroke-width',chosen?'1.5':'.7');stroke.setAttribute('stroke-opacity',chosen?'.48':'.11')});}
hit.addEventListener('mousemove',e=>{const pt=svg.createSVGPoint();pt.x=e.clientX;pt.y=e.clientY;const local=pt.matrixTransform(svg.getScreenCTM().inverse());const t=Math.max(0,Math.min(8,(local.x-L)/(R-L)*8));const k=Math.min(7,Math.floor(t)),frac=t-k;
const candidates=series.filter(s=>active.has(s.name)).map(s=>({s,dist:Math.abs(local.y-yy(interp(s.values[k],s.values[k+1],frac)))})).sort((a,b)=>a.dist-b.dist);
const selected=candidates.length&&candidates[0].dist<85?candidates[0].s:null;highlight(selected?.name||null);if(selected)inspect(host,selected.name,labels[Math.max(0,Math.min(8,Math.round(t)))]+' · 强度 '+selected.values[Math.max(0,Math.min(8,Math.round(t)))]);
const i=Math.max(0,Math.min(8,Math.round(t)));
tip.innerHTML=`<strong>${labels[i]}${selected?' · '+selected.name:''}</strong>`+series.filter(s=>active.has(s.name)).map(s=>`<div style="${selected&&s!==selected?'opacity:.36':''}"><span style="color:${s.color}">●</span> ${esc(s.name)}：<b>${s.values[i]}</b></div>`).join('');tip.style.display='block';const box=chart.getBoundingClientRect(),sx=box.width/chart.clientWidth,sy=box.height/chart.clientHeight;const pointerX=(e.clientX-box.left)/sx,pointerY=(e.clientY-box.top)/sy;tip.style.left=Math.max(0,Math.min(pointerX+18/sx,chart.clientWidth-tip.offsetWidth))+'px';tip.style.top=Math.max(0,Math.min(pointerY-110/sy,chart.clientHeight-tip.offsetHeight))+'px';});hit.addEventListener('mouseleave',()=>{tip.style.display='none';highlight(null)});
};render();root.querySelectorAll('.legend button').forEach(button=>{button.addEventListener('pointerenter',()=>inspect(host,button.dataset.name||button.textContent.trim(),'材质对照'));button.addEventListener('focus',()=>inspect(host,button.dataset.name||button.textContent.trim(),'材质对照'));});
 return ()=>{observer.disconnect();root.replaceChildren();};
}
